use serde_json::json;use sha2::{Digest,Sha256};use std::{fs,path::Path};const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-31-g2-denominator-tree176";
fn h(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn main(){let file=Path::new(D).join("README.md");let original=fs::read_to_string(&file).unwrap();let mut result=String::new();for line in original.lines(){if line.starts_with('|'){result.push_str(line);result.push('\n');continue;}let chars=line.chars().collect::<Vec<_>>();let(mut code,mut link)=(false,false);for(i,&ch)in chars.iter().enumerate(){if ch=='`'{code=!code;}if i>=1&&chars[i-1]==']'&&ch=='('{link=true;}if i>0&&!code&&!link{let previous=chars[i-1];let shape_x=ch=='x'&&previous.is_ascii_digit()&&chars.get(i+1).is_some_and(|x|x.is_ascii_digit());let shape_after_x=previous=='x'&&i>=2&&chars[i-2].is_ascii_digit()&&ch.is_ascii_digit();if (previous.is_ascii_digit()&&ch.is_ascii_alphabetic()&&!shape_x)||(previous.is_ascii_lowercase()&&ch.is_ascii_digit()&&!shape_after_x){result.push(' ');}}result.push(ch);if link&&ch==')'{link=false;}}result.push('\n');}
for(a,b)in[("ratio<1 and≥10/15 wins","ratio < 1 and ≥ 10/15 wins"),("ON/control≤1.03","ON/control ≤ 1.03"),("4–12 of15","4–12 of 15"),("CPU10×","CPU 10×"),("workers, ON/","workers, ON/"),("at200","at 200"),("at352","at 352")]{result=result.replace(a,b);}
// Spacing only: every non-whitespace byte, number, table and link stays exact.
assert_eq!(original.chars().filter(|c|!c.is_whitespace()).collect::<String>(),result.chars().filter(|c|!c.is_whitespace()).collect::<String>());assert_ne!(original,result);fs::write(&file,&result).unwrap();fs::copy("/home/ubuntu/src/zopro-perf-work/g2-denominator-tree176/editorial.rs",Path::new(D).join("artifacts/editorial.rs")).unwrap();let receipt=json!({"only_whitespace_changed":true,"original_sha256":h(original.as_bytes()),"final_sha256":h(result.as_bytes()),"original_nonwhitespace_equals_final":true,"raw_captures_gates_and_archives_unchanged":true});fs::write(Path::new(D).join("artifacts/editorial-review.json"),serde_json::to_vec_pretty(&receipt).unwrap()).unwrap();let mut files=vec![];for entry in fs::read_dir(D).unwrap(){let p=entry.unwrap().path();if p.is_file()&&p.file_name().unwrap()!="SHA256SUMS"{files.push(p);}}for entry in fs::read_dir(Path::new(D).join("artifacts")).unwrap(){let p=entry.unwrap().path();assert!(p.is_file());files.push(p);}files.sort();let mut sums=String::new();for p in files{sums.push_str(&format!("{}  {}\n",h(&fs::read(&p).unwrap()),p.strip_prefix(D).unwrap().display()));}fs::write(Path::new(D).join("SHA256SUMS"),sums).unwrap();println!("Editorial PASS:whitespace only,all non-whitespace bytes and table numbers exact");}
